/// <reference types="node" />
import { neon } from '@neondatabase/serverless';
import { drizzle } from 'drizzle-orm/neon-http';
import * as schema from './schema';

// Validamos que la variable de entorno exista
if (!process.env.DATABASE_URL) {
  throw new Error('Falta la variable de entorno DATABASE_URL en el archivo .env.local');
}

// Creamos el cliente HTTP de Neon optimizado para serverless
const sql = neon(process.env.DATABASE_URL);

// Inicializamos Drizzle pasándole el cliente y el esquema
export const db = drizzle(sql, { schema });