'use server';

import { db } from '../lib/db';
import { transactions } from '../lib/schema';
import { revalidatePath } from 'next/cache';

export async function addTransaction(formData: FormData) {
  const concept = formData.get('concept') as string;
  const amountStr = formData.get('amount') as string;
  const type = formData.get('type') as string; // 'ingreso' o 'gasto'
  const category = formData.get('category') as string;

  if (!concept || !amountStr || !type || !category) {
    throw new Error('Por favor completa todos los campos requeridos.');
  }

  const numericAmount = parseFloat(amountStr);

  try {
    // Insertamos la transacción en la base de datos de Neon
    await db.insert(transactions).values({
      userId: 1, // Por ahora asignamos el usuario ID 1 temporalmente mientras configuramos la sesión
      coupleId: null, // Individual por defecto
      amount: numericAmount.toString(),
      type: type,
      category: category,
      description: concept,
    });

    // Refrescamos la página para que se actualice la lista de movimientos
    revalidatePath('/');
  } catch (error) {
    console.error('Error al guardar la transacción:', error);
    throw new Error('No se pudo guardar la transacción.');
  }
}