import { pgTable, text, serial, timestamp, numeric, integer } from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';

// 1. TABLA DE USUARIOS
export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  password: text('password').notNull(), // Contraseña hasheada
  coupleId: integer('couple_id'), // Relación opcional con la tabla de parejas
  createdAt: timestamp('created_at').defaultNow().notNull(),
});

// 2. TABLA DE PAREJAS (Para el sistema de código QR)
export const couples = pgTable('couples', {
  id: serial('id').primaryKey(),
  inviteCode: text('invite_code').notNull().unique(), // Código único que representará el QR
  createdAt: timestamp('created_at').defaultNow().notNull(),
});

// 3. TABLA DE TRANSACCIONES (Ingresos y Gastos manuales)
export const transactions = pgTable('transactions', {
  id: serial('id').primaryKey(),
  userId: integer('user_id').notNull(), // Quién registró el movimiento
  coupleId: integer('couple_id'), // Si tiene valor, el gasto es compartido en pareja; si es null, es individual
  amount: numeric('amount', { precision: 10, scale: 2 }).notNull(), // Monto (ej. 150.50)
  type: text('type').notNull(), // 'ingreso' o 'gasto'
  category: text('category').notNull(), // 'Comida', 'Servicios', 'Ocio', etc.
  description: text('description'), // Nota opcional
  date: timestamp('date').defaultNow().notNull(), // Fecha del movimiento
  createdAt: timestamp('created_at').defaultNow().notNull(),
});

// --- RELACIONES (Para que Drizzle entienda cómo se conectan) ---

export const usersRelations = relations(users, ({ one, many }) => ({
  couple: one(couples, {
    fields: [users.coupleId],
    references: [couples.id],
  }),
  transactions: many(transactions),
}));

export const couplesRelations = relations(couples, ({ many }) => ({
  users: many(users),
  transactions: many(transactions),
}));

export const transactionsRelations = relations(transactions, ({ one }) => ({
  user: one(users, {
    fields: [transactions.userId],
    references: [users.id],
  }),
  couple: one(couples, {
    fields: [transactions.coupleId],
    references: [couples.id],
  }),
}));